 'a+bT+cT2+dexp(-kT)': (lambda p,T: p[0]+p[1]*T+p[2]*T**2+p[3]*np.exp(-p[4]*T), 5),
 'a+b/T+cexp(-kT)': (lambda p,T: p[0]+p[1]/T+p[2]*np.exp(-p[3]*T), 4),
