 'a+bexp(-k/T)+cT': (lambda p,T: p[0]+p[1]*np.exp(-p[2]/T)+p[3]*T, 4),
 'a+bT+c*exp(-k/T)': (lambda p,T: p[0]+p[1]*T+p[2]*np.exp(-p[3]/T), 4),
 'a+b*exp(-k*T)+c*exp(-m/T)': (lambda p,T: p[0]+p[1]*np.exp(-p[2]*T)+p[3]*np.exp(-p[4]/T), 5),
 'a+bT+cT^2+dT^3+e/T': (lambda p,T: p[0]+p[1]*T+p[2]*T**2+p[3]*T**3+p[4]/T, 5),
}
for name,(h,n) in fams.items():
    best=None
    rng=np.random.default_rng(3)
    for i in range(30):
        p0=np.concatenate([rng.normal(0,1,n),[rng.uniform(0.2,1.5)]*0+[31.4,0.756]])
